using Autodesk.Revit.DB;
using Autodesk.Revit.Creation;

// Start a transaction
using (Transaction trans = new Transaction(Document, "Create Wall"))
{
    trans.Start();

    // Get the level to place the wall on
    Level level = new FilteredElementCollector(Document)
                    .OfClass(typeof(Level))
                    .Cast<Level>()
                    .FirstOrDefault();

    if (level == null)
    {
        throw new InvalidOperationException("No level found in the document.");
    }

    // Define the wall line
    XYZ startPoint = new XYZ(0, 0, 0);
    XYZ endPoint = new XYZ(10, 0, 0); // 10 meters length
    Line wallLine = Line.CreateBound(startPoint, endPoint);

    // Get a basic wall type
    WallType wallType = new FilteredElementCollector(Document)
                        .OfClass(typeof(WallType))
                        .Cast<WallType>()
                        .FirstOrDefault(wt => wt.Kind == WallKind.Basic);

    if (wallType == null)
    {
        throw new InvalidOperationException("No basic wall type found.");
    }

    // Create the wall
    Wall wall = Wall.Create(Document, wallLine, wallType.Id, level.Id, 3, 0, false, false); // height 3 meters

    trans.Commit();
}
```

